#include "contract_test.h"
#include "layernorm_engine.h"
int main(){using namespace laya;LayerNormTask t;t.ctx=test::ctx(Op::LN_EMB,1);t.src=test::ref(Buffer::HIDDEN);t.dst=test::ref(Buffer::NORM);t.gamma=1;test::require(layernorm_engine::validate(t,2,128),"LN emb");t.src=none();test::require(!layernorm_engine::validate(t,2,128),"LN src required");t.src=test::ref(Buffer::HIDDEN);t.eps_bits=0;test::require(!layernorm_engine::validate(t,2,128),"eps exact bits");t.eps_bits=0x3727c5ac;t.ctx=test::ctx(Op::LN_ATTN,2,0);t.gamma=0;test::require(!layernorm_engine::validate(t,2,128),"encoder0 skips LN attn");t.ctx=test::ctx(Op::LN_ATTN,2,1);test::require(layernorm_engine::validate(t,2,128),"HIDDEN to NORM");t.src=test::ref(Buffer::QKV);test::require(!layernorm_engine::validate(t,2,128),"QKV cannot feed LN");t.src=test::ref(Buffer::WI);t.dst=test::ref(Buffer::DEC_FF);test::require(!layernorm_engine::validate(t,2,128),"WI/DEC_FF alias not LN");}
